using System;
using System.Linq;
using System.Collections;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed class RivalRaceDirector:MonoBehaviour,IFinchRecoveryHandler {
 public static RivalRaceDirector Instance;public DocksideTrialDirector Trial;public DuelRaceSession Race{get;private set;}public RoadPilot Opponent{get;private set;}public bool Panel{get;private set;}public bool Results{get;private set;}public string Message{get;private set;}public bool Ready{get;private set;}public bool SavePending{get;private set;}public string SelectedRival="rookie";public bool Pinks,StakeConfirmed;RivalsData data;Vector3 previousPlayer,previousRival;double lastTime;LineRenderer line;TextMesh gate;Material routeMaterial;float rivalStall;int lastRivalGate;string appliedCar;int fleetPage;bool hidHud,priorHudEnabled;
 public static void Hook(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="HarborVale_CityMap")new GameObject("Rivals | cash races, title stakes and fleet").AddComponent<RivalRaceDirector>();}
 IEnumerator Start(){Instance=this;while((Trial=FindAnyObjectByType<DocksideTrialDirector>())?.Store==null||FindAnyObjectByType<ExpandedWorkshop>()?.Ready!=true)yield return null;data=RivalsData.Load();Trial.vehicle.RecoveryHandler=this;lastTime=Time.realtimeSinceStartupAsDouble;try{if(Trial.Store.Profile.fleet.HasPending){Trial.Store.ForfeitDuel();Message="Interrupted race forfeited under its agreed terms. Your saved fleet is restored.";}ApplyVehicle();}catch(Exception e){SavePending=true;Message=e.Message;Panel=true;}CreateNavigation();Ready=true;}
 public bool OpenPanel(){if(!Ready||Race!=null||Trial.Active||Trial.ShowingResult||Trial.vehicle.controlsLocked||Trial.vehicle.SpeedKph>=5||FindAnyObjectByType<ExpandedWorkshop>()?.IsOpen==true)return false;Panel=true;Trial.ExternalModalOpen=true;Trial.vehicle.controlsLocked=true;StakeConfirmed=false;return true;}
 public void ClosePanel(){if(SavePending||Race!=null)return;Panel=false;Showroom=false;VehicleShowroom.Close();Results=false;Trial.ExternalModalOpen=false;Trial.vehicle.controlsLocked=false;}
 public bool StartRace(){if(!Panel||SavePending||Race!=null||Pinks&&!StakeConfirmed)return false;try{var store=Trial.Store;var contract=store.BeginDuel(Guid.NewGuid().ToString("N"),SelectedRival,Pinks?"pinks":"cash");Race=new DuelRaceSession(contract,Trial.Definition);var first=Trial.Definition.checkpoints[0];var world=FindAnyObjectByType<TrafficWorld>();if(world!=null){world.RaceReserved=true;world.ClearGrid(first.Position);}Trial.vehicle.ResetAt(first.Position-first.Forward*12-Vector3.Cross(Vector3.up,first.Forward)*1.7f+Vector3.up*.35f,Quaternion.LookRotation(first.Forward));var car=TrafficWorld.CreateCar(contract.opponentName,contract.opponentBuild,contract.paint,contract.opponentModelId);Opponent=car.gameObject.AddComponent<RoadPilot>();Opponent.Car=car;Opponent.Path=Trial.Definition.route.Select(p=>p.Position).ToArray();Opponent.IsRival=true;Opponent.CruiseKph=contract.speedKph;Opponent.Index=0;Opponent.Lane=1.7f;Opponent.Held=true;TrafficWorld.Agents.Add(Opponent);car.ResetAt(first.Position-first.Forward*12+Vector3.Cross(Vector3.up,first.Forward)*1.7f+Vector3.up*.35f,Quaternion.LookRotation(first.Forward));previousPlayer=Trial.vehicle.transform.position;previousRival=car.transform.position;Trial.vehicle.controlsLocked=true;Panel=false;Results=false;rivalStall=0;lastRivalGate=0;Message=null;line.enabled=true;Camera.main?.GetComponent<FinchChaseCamera>()?.Snap();lastTime=Time.realtimeSinceStartupAsDouble;return true;}catch(Exception e){Message=e.Message;return false;}}
 void CreateNavigation(){routeMaterial=new Material(Shader.Find("Sprites/Default"));routeMaterial.color=new Color(.2f,.9f,.7f);var g=new GameObject("Rival road route | visual only");g.transform.SetParent(transform,false);line=g.AddComponent<LineRenderer>();line.sharedMaterial=routeMaterial;line.widthMultiplier=.15f;line.positionCount=Trial.Definition.route.Length;line.SetPositions(Trial.Definition.route.Select(p=>p.Position+Vector3.up*.15f).ToArray());line.enabled=false;var label=new GameObject("Next rival checkpoint");label.transform.SetParent(transform,false);gate=label.AddComponent<TextMesh>();gate.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");gate.fontSize=48;gate.characterSize=.15f;gate.anchor=TextAnchor.MiddleCenter;gate.alignment=TextAlignment.Center;gate.color=new Color(.25f,1,.75f);label.GetComponent<Renderer>().sharedMaterial=gate.font.material;label.SetActive(false);}
 void Update(){if(!Ready)return;double now=Time.realtimeSinceStartupAsDouble;float dt=(float)Math.Max(0,now-lastTime);lastTime=now;if(Race!=null&&!Results){Race.Tick(dt,previousPlayer,Trial.vehicle.transform.position,previousRival,Opponent.Car.transform.position);previousPlayer=Trial.vehicle.transform.position;previousRival=Opponent.Car.transform.position;if(Race.Rival.NextGate==lastRivalGate)rivalStall+=dt;else{lastRivalGate=Race.Rival.NextGate;rivalStall=0;}if(!Race.Resolved&&Race.Rival.State==TrialState.Running&&(rivalStall>45||Opponent.NeedsAssistedReset)){Opponent.RecoverAt(Race.Rival.Recover());previousRival=Opponent.transform.position;rivalStall=0;}if(Race.Resolved)CommitResult();}if(FinchInput.Shortcut(KeyCode.H)){if(Panel)ClosePanel();else OpenPanel();}if(FinchInput.Shortcut(KeyCode.Escape)){if(Race!=null&&!Results){Race.Forfeit();CommitResult();}else if(Panel&&!SavePending)ClosePanel();}if(gate!=null&&Race!=null&&!Results){int i=Math.Min(Race.Player.NextGate,Trial.Definition.checkpoints.Length-1);gate.transform.position=Trial.Definition.checkpoints[i].Position+Vector3.up*4;gate.text="CHECKPOINT "+(i+1)+" / "+Trial.Definition.checkpoints.Length;gate.gameObject.SetActive(true);if(Camera.main!=null)gate.transform.rotation=Camera.main.transform.rotation;}else if(gate!=null)gate.gameObject.SetActive(false);}
 void LateUpdate(){if(!Ready)return;var hud=Trial.vehicle.GetComponent<FinchDrivingHUD>();if(Panel&&!hidHud&&hud!=null){priorHudEnabled=hud.enabled;hud.enabled=false;hidHud=true;}else if(!Panel&&hidHud&&hud!=null){hud.enabled=priorHudEnabled;hidHud=false;}bool modal=Panel||Race!=null||SavePending;if(modal){Trial.ExternalModalOpen=true;Trial.vehicle.controlsLocked=Panel||Results||SavePending||Race?.Player.State==TrialState.Countdown;Trial.vehicle.countdownStagingAllowed=Race!=null&&!Results&&Race.Player.State==TrialState.Countdown;if(Opponent!=null){Opponent.Held=Results||Race.Rival.State!=TrialState.Running;Opponent.Car.controlsLocked=Opponent.Held;}}}
 void CommitResult(){try{Trial.Store.SettleDuel(Race);SavePending=false;Results=true;Panel=true;Message=Race.Result=="draw"?"Draw. Both titles stay with their owners; cash mode pays the completion reward.":Race.Result=="win"?(Race.Contract.mode=="pinks"?"You won the rival's car. Return to driving, then H to select it.":"Victory! "+Race.Contract.winCredits+" credits saved."):Race.Contract.mode=="pinks"?"Your staked car transferred to the rival. Remaining cars and the recovery loaner are available.":Race.Result=="finish"?"Race finished. "+Race.Contract.finishCredits+" credits saved.":"Race forfeited. No cash reward.";ApplyVehicle();}catch(Exception e){SavePending=true;Panel=true;Message="Result not saved: "+e.Message+" — retry before leaving.";}}
 public void ReturnToRoad(){if(SavePending)return;if(Opponent!=null){TrafficWorld.Agents.Remove(Opponent);Destroy(Opponent.gameObject);}Race=null;Opponent=null;Results=false;Panel=false;line.enabled=false;Trial.ExternalModalOpen=false;Trial.vehicle.controlsLocked=false;Trial.vehicle.countdownStagingAllowed=false;var traffic=FindAnyObjectByType<TrafficWorld>();if(traffic!=null)traffic.RaceReserved=false;}
 public bool BeforeLeave(){if(SavePending){Message="Save the committed result before leaving.";return false;}if(Race!=null&&!Race.Resolved){Race.Forfeit();CommitResult();if(SavePending)return false;}return true;}
 public bool TryRecover(FinchVehicle vehicle){if(Race==null||Results)return Trial.TryRecover(vehicle);if(Race.Player.State!=TrialState.Running)return true;var g=Race.Player.Recover();vehicle.ResetAt(g.Position-g.Forward*5+Vector3.up*.4f,Quaternion.LookRotation(g.Forward));previousPlayer=vehicle.transform.position;Camera.main?.GetComponent<FinchChaseCamera>()?.Snap();return true;}
 public void ApplyVehicle(){var store=Trial.Store;FindAnyObjectByType<ExpandedWorkshop>()?.SyncCareer();Trial.vehicle.displayName=store.ActiveVehicleName;int paint=store.Profile.fleet.selectedId==FleetLedger.Loaner?4:FleetLedger.Find(store.Profile.fleet,store.Profile.fleet.selectedId).paint;TrafficWorld.Paint(Trial.vehicle,paint);appliedCar=store.Profile.fleet.selectedId;}
 public bool SelectCar(string id){if(Race!=null||!Panel||SavePending)return false;try{Trial.Store.SelectVehicle(Guid.NewGuid().ToString("N"),id);ApplyVehicle();Message="Selected "+Trial.Store.ActiveVehicleName;return true;}catch(Exception e){Message=e.Message;return false;}}
 public bool BuyCar(){if(Race!=null||!Panel||SavePending)return false;try{Trial.Store.BuyReplacement(Guid.NewGuid().ToString("N"));ApplyVehicle();Message="Replacement Finch purchased and selected.";return true;}catch(Exception e){Message=e.Message;return false;}}
 public bool Showroom{get;private set;}public void OpenShowroom(){if(Panel&&Race==null&&!SavePending)Showroom=true;}
 void OnGUI(){if(!Ready)return;GUI.depth=-1000;if(Showroom){VehicleShowroom.Draw(this,()=>Showroom=false);return;}if(!Panel){if(Race==null&&!Trial.ExternalModalOpen&&!Trial.Active&&!Trial.ShowingResult)GUI.Box(new Rect(16,164,440,30),"H — Rivals & owned cars · Stop to open");else if(Race!=null){var s=new GUIStyle(GUI.skin.box){fontSize=19};GUI.Box(new Rect(Screen.width/2-300,Screen.height-190,600,92),Race.Player.State==TrialState.Countdown?"RIVAL RACE / "+Mathf.CeilToInt(Race.Player.Countdown)+"\n"+Race.Contract.opponentName:Race.Contract.opponentName+" / "+Race.Contract.mode.ToUpperInvariant()+"\nGate "+Race.Player.NextGate+" / "+Trial.Definition.checkpoints.Length+" · "+Race.Player.Elapsed.ToString("F1")+"s\nEsc = forfeit" ,s);}return;}
  var old=GUI.matrix;GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1280f,Screen.height/800f,1));var color=GUI.color;GUI.color=new Color(.035f,.06f,.085f);GUI.DrawTexture(new Rect(0,0,1280,800),Texture2D.whiteTexture);GUI.color=color;var title=new GUIStyle(GUI.skin.label){fontSize=30,fontStyle=FontStyle.Bold};title.normal.textColor=new Color(.22f,.87f,.76f);var text=new GUIStyle(GUI.skin.label){fontSize=17,wordWrap=true};var button=new GUIStyle(GUI.skin.button){fontSize=18};button.normal.background=Texture2D.whiteTexture;button.hover.background=Texture2D.whiteTexture;button.active.background=Texture2D.whiteTexture;button.normal.textColor=button.hover.textColor=button.active.textColor=Color.white;var priorBackground=GUI.backgroundColor;GUI.backgroundColor=new Color(.12f,.22f,.28f);var toggle=new GUIStyle(GUI.skin.toggle){fontSize=17,wordWrap=true};GUI.Box(new Rect(48,38,1184,724),"");GUI.Label(new Rect(76,58,900,44),"HARBOR VALE / RIVALS & FLEET",title);GUI.Label(new Rect(76,109,1090,40),Trial.Store.Profile.availableCredits.ToString("N0")+" cr   ·   "+Trial.Store.ActiveVehicleName,text);
  GUI.enabled=Race==null&&!SavePending;for(int i=0;i<data.opponents.Length;i++){var o=data.opponents[i];if(GUI.Button(new Rect(76+i*370,159,354,72),(SelectedRival==o.id?"✓ ":"")+o.name+"\n"+o.winCredits+" cr win / "+o.finishCredits+" cr finish",button)){SelectedRival=o.id;StakeConfirmed=false;}}
  bool pink=GUI.Toggle(new Rect(78,248,290,32),Pinks,"Race for pink slips (optional)",toggle);if(pink!=Pinks){Pinks=pink;StakeConfirmed=false;}var option=Array.Find(data.opponents,o=>o.id==SelectedRival);var optionModel=string.IsNullOrEmpty(option.modelId)?"car_finch":option.modelId;var specs=WorkshopCatalog.Load(optionModel).Resolve(option.build);GUI.Label(new Rect(76,285,1090,55),"Rival: "+(optionModel=="car_finch"?"Aster Finch":VehicleLineup.Find(optionModel).name)+" / "+ChassisTuning.CrankHp(specs).ToString("F0")+" HP · "+specs.massKg.ToString("F0")+" kg. Same real vehicle physics; no rubber-band speed boosts. Street traffic remains active.",text);
  if(Pinks){GUI.Label(new Rect(76,343,1090,54),"Stake: "+Trial.Store.ActiveVehicleName+" INCLUDING its upgrades. A win transfers the rival's car to you. Losing, leaving or closing the game during a committed race transfers your car permanently. Ties keep both titles.",text);StakeConfirmed=GUI.Toggle(new Rect(78,402,1080,32),StakeConfirmed,"I agree to stake this specific car and all installed upgrades. A loaner cannot be staked.",toggle);}else GUI.Label(new Rect(76,347,1090,54),"Cash race: no entry fee, no car ownership risk. Finish the full marked loop to earn the displayed reward. Abandoning gives nothing. Free loaner cash races can fund a replacement car.",text);
  GUI.enabled=Race==null&&!SavePending&&(!Pinks||StakeConfirmed&&Trial.Store.Profile.fleet.selectedId!=FleetLedger.Loaner);if(GUI.Button(new Rect(76,446,1090,46),Pinks?"Confirm stakes & start race":"Start cash race",button))StartRace();GUI.enabled=Race==null&&!SavePending;
  GUI.Label(new Rect(76,505,1090,28),"OWNED CARS / select while stopped",text);int pages=Math.Max(1,(Trial.Store.Profile.fleet.cars.Count(c=>c.owner=="player")+5)/6);fleetPage=Mathf.Clamp(fleetPage,0,pages-1);if(GUI.Button(new Rect(978,502,80,28),"Previous"))fleetPage=Math.Max(0,fleetPage-1);if(GUI.Button(new Rect(1066,502,100,28),"Next / "+pages))fleetPage=Math.Min(pages-1,fleetPage+1);int n=0;foreach(var car in Trial.Store.Profile.fleet.cars.Where(c=>c.owner=="player").Skip(fleetPage*6).Take(6)){if(GUI.Button(new Rect(76+n%3*370,541+n/3*42,354,36),(Trial.Store.Profile.fleet.selectedId==car.id?"✓ ":"")+car.name,button))SelectCar(car.id);n++;}if(n==0)GUI.Label(new Rect(76,540,1080,32),"No owned cars. Recovery loaner supplied free; earn credits in cash races/time trials.",text);
  GUI.enabled=Race==null&&!SavePending;if(GUI.Button(new Rect(76,636,350,40),"Buy basic Finch · "+data.replacementPrice+" cr",button))BuyCar();GUI.enabled=true;if(GUI.Button(new Rect(443,636,260,40),"Browse new cars",button))OpenShowroom();GUI.Label(new Rect(720,632,446,61),Message??"Your original car's identity and paid history are preserved. Pink-slip transfers save atomically.",text);
  if(SavePending){if(GUI.Button(new Rect(76,703,1090,38),"Retry saving committed result",button)){if(Race!=null)CommitResult();else{try{Trial.Store.ForfeitDuel();SavePending=false;ApplyVehicle();}catch(Exception e){Message=e.Message;}}}}else if(GUI.Button(new Rect(76,703,1090,38),Results?"Return to driving":"Close / return to driving",button)){if(Results)ReturnToRoad();else ClosePanel();}GUI.enabled=true;GUI.backgroundColor=priorBackground;GUI.matrix=old;
 }
 void OnDestroy(){VehicleShowroom.Close();if(Instance==this)Instance=null;if(routeMaterial!=null)Destroy(routeMaterial);}
}
